PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS Users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_salt TEXT NOT NULL,password_hash TEXT NOT NULL,company TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,token_hash TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES Users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON Sessions(expires_at);
CREATE TABLE IF NOT EXISTS Services(id INTEGER PRIMARY KEY AUTOINCREMENT,category TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',base_price INTEGER NOT NULL DEFAULT 0 CHECK(base_price>=0),currency TEXT NOT NULL DEFAULT 'INR',is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)));
CREATE TABLE IF NOT EXISTS Leads(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',service TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Orders(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES Users(id),service_id INTEGER NOT NULL REFERENCES Services(id),package TEXT NOT NULL DEFAULT '',details TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),currency TEXT NOT NULL DEFAULT 'INR',status TEXT NOT NULL DEFAULT 'Pending Payment',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_orders_user ON Orders(user_id,created_at);
CREATE TABLE IF NOT EXISTS Payments(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT NOT NULL REFERENCES Orders(id),gateway TEXT NOT NULL,gateway_order_id TEXT NOT NULL,gateway_payment_id TEXT,amount INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'INR',status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_payments_gateway_order ON Payments(gateway,gateway_order_id);
CREATE TABLE IF NOT EXISTS Documents(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT NOT NULL REFERENCES Orders(id),user_id INTEGER NOT NULL REFERENCES Users(id),file_name TEXT NOT NULL,file_key TEXT NOT NULL UNIQUE,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,uploaded_at TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN (0,1)));
INSERT INTO Services(category,name,description,base_price,currency,is_active) SELECT 'Business Registration','GST Registration Assistance','Assistance with GST registration requirements and application preparation.',0,'INR',1 WHERE NOT EXISTS(SELECT 1 FROM Services WHERE name='GST Registration Assistance');
